"""Post-freeze held-case creation with value-free, label-independent addresses."""

from collections import Counter
import json
import string

import numpy as np

from legacy_v3.numeric_graph import SERIES_NAMES
from .contracts import INTENTS, file_identity, sha256
from .graph_assets import Assets, DOMAINS
from .joint_binding import (
    GATES as GATES,
    PROJECT as PROJECT,
    SEEDS as SEEDS,
    verify_freeze as verify_freeze,
)
from .joint_binding import immutable_path, relative_path


OFFSETS = {
    "at": [0],
    "previous": [-1],
    "change": [-1, 0],
    "mean3": [-2, -1, 0],
    "range3": [-2, -1, 0],
    "peak3": [-2, -1, 0],
}


def load_held(path, frozen):
    path = immutable_path(path)
    seal_path = immutable_path(path.parent / "SEAL.json")
    raw = seal_path.read_bytes()
    if sha256(raw) != frozen["held_seal_sha256"]:
        raise ValueError("independent held seal differs from pre-execution freeze")
    seal = json.loads(raw)
    if (
        seal["schema"] != "hepta.memory.v5.held-seal.v1"
        or seal["sealed"] is not True
        or seal["evaluated_by_any_router"] is not False
    ):
        raise ValueError("held authoring/seal boundary differs")
    if path.name != seal["corpus_file"] or path.name not in seal["files"]:
        raise ValueError("held language file differs from sealed source")
    corpus_raw = None
    for name, expected in seal["files"].items():
        source = immutable_path(path.parent.joinpath(*relative_path(name).parts))
        payload = source.read_bytes()
        if {"bytes": len(payload), "sha256": sha256(payload)} != expected:
            raise ValueError("held seal file bytes differ: " + name)
        if source == path:
            corpus_raw = payload
    if corpus_raw is None:
        raise ValueError("held corpus is absent from the complete seal inventory")
    if seal["inference_fields"] != ["utterance", "series_name", "date"]:
        raise ValueError("held inference field contract differs")
    document = json.loads(corpus_raw)
    if (
        set(document) != {"schema", "queries"}
        or document["schema"] != "hepta.memory.v5.sealed-language.v1"
    ):
        raise ValueError("held corpus schema differs")
    rows = document["queries"]
    required = {
        "query_id",
        "utterance",
        "series_name",
        "date",
        "gold_intent",
        "ood_family",
        "risk_group",
        "partition",
        "language",
        "allow_numeric_read",
        "expected_provenance_offsets",
        "requested_operator",
        "label_reason",
    }
    if len(rows) != 216 or len({row["query_id"] for row in rows}) != 216:
        raise ValueError("held inventory must contain 216 independent template IDs")
    counts = Counter()
    families = Counter()
    for row in rows:
        if (
            set(row) != required
            or row["partition"] != "sealed_held_v5"
            or row["language"] != "en"
        ):
            raise ValueError("held row fields or partition differ")
        if row["series_name"] != "{series_name}" or row["date"] != "{date}":
            raise ValueError("held slots must not encode task labels")
        fields = []
        for _, field, spec, conversion in string.Formatter().parse(row["utterance"]):
            if field is not None:
                if field not in {"series_name", "date"} or spec or conversion:
                    raise ValueError("unsupported held template interpolation")
                fields.append(field)
        if set(fields) != {"series_name", "date"}:
            raise ValueError("held template must include both explicit address slots")
        intent = row["gold_intent"]
        if intent is None:
            if (
                row["risk_group"] != "near"
                or row["allow_numeric_read"] is not False
                or not row["ood_family"]
            ):
                raise ValueError("held OOD annotations disagree")
            families[row["ood_family"]] += 1
        else:
            if (
                intent not in INTENTS
                or row["risk_group"] != "known"
                or row["ood_family"] is not None
                or row["allow_numeric_read"] is not True
                or row["expected_provenance_offsets"] != OFFSETS[intent]
            ):
                raise ValueError("held supported-operation annotations disagree")
            counts[intent] += 1
    if (
        counts != Counter({intent: 24 for intent in INTENTS})
        or len(families) != 12
        or set(families.values()) != {6}
    ):
        raise ValueError("held intent/OOD family denominators differ")
    if (
        seal["counts"]["total"] != 216
        or seal["counts"]["known"] != 144
        or seal["counts"]["near_ood"] != 72
    ):
        raise ValueError("held seal denominator differs")
    if (
        seal["counts"]["per_intent"] != dict(counts)
        or seal["counts"]["per_ood_family"] != dict(families)
        or seal["corpus_schema"] != document["schema"]
    ):
        raise ValueError("held seal per-class inventory or corpus schema differs")
    return rows, {
        "seal": file_identity(seal_path),
        "corpus": file_identity(path),
        "counts": seal["counts"],
    }


def previous_month(address, offset):
    serial = address[0] * 12 + address[1] - 1 + offset
    return serial // 12, serial % 12 + 1


def uniform_addresses(reader, count, seed, domain):
    positions = {year: index for index, year in enumerate(reader.years)}
    valid = []
    for year in reader.years:
        for month in range(1, 13):
            addresses = [
                previous_month((year, month), offset) for offset in (-2, -1, 0)
            ]
            if all(
                y in positions and reader.bank.mask[positions[y], m - 1]
                for y, m in addresses
            ):
                valid.append((year, month))
    if not valid:
        raise ValueError("no available complete three-month windows")
    indices = np.arange(count, dtype=np.int64) * len(valid) // count
    order = np.random.default_rng(
        seed + 7919 + DOMAINS.index(domain) * 104729
    ).permutation(count)
    chosen = [valid[int(indices[index])] for index in order]
    return chosen, {
        "eligible_three_month_addresses": len(valid),
        "requested_addresses": count,
        "unique_selected_addresses": len(set(chosen)),
        "selection": "uniform rank grid, then seed/domain-only permutation",
        "labels_predictions_and_numeric_values_used": False,
    }


def independent_target(exact, domain, intent, address):
    if intent is None:
        return None
    positions = {year: index for index, year in enumerate(exact.years)}
    coordinates = [previous_month(address, offset) for offset in OFFSETS[intent]]
    values = []
    for year, month in coordinates:
        if year not in positions or not exact.mask[positions[year], month - 1]:
            raise ValueError("grader address is absent from the exact source")
        values.append(int(exact.matrix[positions[year], month - 1]))
    if intent in {"at", "previous"}:
        value = values[0]
    elif intent == "change":
        value = values[1] - values[0]
    elif intent == "mean3":
        value = (values[0] + values[1] + values[2]) / 3
    elif intent == "range3":
        value = max(values) - min(values)
    else:
        value = max(values)
    return {
        "kind": "number",
        "value": value,
        "support": [f"{domain}:{year:04d}-{month:02d}" for year, month in coordinates],
    }


def make_cases(templates, assets_directory, domain, seed):
    assets = Assets(assets_directory)
    parameter = assets.parameter(domain)
    exact, exact_info = assets.exact(domain)
    if parameter.years != exact.years or not np.array_equal(
        parameter.bank.mask, exact.mask
    ):
        raise ValueError("parameter and exact address availability differ")
    addresses, schedule = uniform_addresses(parameter, len(templates), seed, domain)
    requests, graders = [], []
    for index, (template, address) in enumerate(zip(templates, addresses, strict=True)):
        date = f"{address[0]:04d}-{address[1]:02d}"
        request = {
            "utterance": template["utterance"].format(
                series_name=SERIES_NAMES[domain], date=date
            ),
            "series_name": SERIES_NAMES[domain],
            "date": date,
        }
        target = independent_target(exact, domain, template["gold_intent"], address)
        requests.append(request)
        graders.append(
            {
                "index": index,
                "template_id": template["query_id"],
                "gold_intent": template["gold_intent"],
                "ood_family": template["ood_family"],
                "address": list(address),
                "target": target,
                "authored_expected_provenance_offsets": template[
                    "expected_provenance_offsets"
                ],
                "requested_operator": template["requested_operator"],
                "label_reason": template["label_reason"],
            }
        )
    return (
        requests,
        graders,
        {
            "address_schedule": schedule,
            "strong_source": exact_info,
            "source_files": assets.verify_consumed(),
        },
    )

memory-cell-v5/v5/joint_grading.py:
"""Exact numeric and ordered-source grading, separate from serving callbacks."""

from collections import Counter
import math

from .contracts import INTENTS, REJECT
from .joint_cases import GATES


def exact_result(actual, target):
    if target is None or actual is None or not isinstance(actual, dict):
        return False
    return (
        set(actual) == {"kind", "value", "support"}
        and actual["kind"] == "number"
        and type(actual["value"]) in (int, float)
        and math.isfinite(actual["value"])
        and actual["value"] == target["value"]
        and list(actual["support"]) == target["support"]
    )


def route_metrics(graders, decisions):
    if len(graders) != len(decisions):
        raise ValueError("route denominator differs from grader")
    known = [i for i, row in enumerate(graders) if row["gold_intent"] is not None]
    ood = [i for i, row in enumerate(graders) if row["gold_intent"] is None]
    correct = sum(
        decisions[i]["accepted_intent"] == graders[i]["gold_intent"] for i in known
    )
    false_accept = sum(decisions[i]["accepted_intent"] is not None for i in ood)
    confusion, raw = Counter(), Counter()
    for row, decision in zip(graders, decisions, strict=True):
        gold = row["gold_intent"] or REJECT
        confusion[gold, decision["accepted_intent"] or REJECT] += 1
        raw[gold, decision["raw_label"]] += 1
    per_intent = {}
    for intent in INTENTS:
        indices = [i for i, row in enumerate(graders) if row["gold_intent"] == intent]
        per_intent[intent] = {
            "queries": len(indices),
            "correct_accepted": sum(
                decisions[i]["accepted_intent"] == intent for i in indices
            ),
            "raw_correct": sum(decisions[i]["raw_label"] == intent for i in indices),
        }
    return {
        "known_queries": len(known),
        "ood_queries": len(ood),
        "known_correct_accepted": correct,
        "known_correct_accepted_fraction": correct / len(known),
        "ood_false_accepted": false_accept,
        "ood_false_accept_fraction": false_accept / len(ood),
        "raw_known_correct": sum(
            decisions[i]["raw_label"] == graders[i]["gold_intent"] for i in known
        ),
        "raw_ood_false_accepted": sum(
            decisions[i]["raw_label"] in INTENTS for i in ood
        ),
        "per_intent": per_intent,
        "accepted_confusion": [
            {"gold": key[0], "prediction": key[1], "count": value}
            for key, value in sorted(confusion.items())
        ],
        "raw_confusion": [
            {"gold": key[0], "prediction": key[1], "count": value}
            for key, value in sorted(raw.items())
        ],
    }


def grade_domain(graders, actual_rows, strong_rows, oracle_rows):
    count = len(graders)
    if any(len(rows) != count for rows in (actual_rows, strong_rows, oracle_rows)):
        raise ValueError("joint arm row counts differ")
    decisions = [row["decision"] for row in actual_rows]
    if decisions != [row["decision"] for row in strong_rows]:
        raise ValueError(
            "actual and strong fresh processes have different route decisions"
        )
    metrics = route_metrics(graders, decisions)
    arm_values = {
        **{
            name: [row["arms"][name] for row in actual_rows]
            for name in (
                "parameter_connected",
                "parameter_removed",
                "parameter_permuted",
            )
        },
        "strong_planner": [row["arms"]["strong_planner"] for row in strong_rows],
        "parameter_oracle": [row["parameter_oracle"] for row in oracle_rows],
        "strong_oracle": [row["strong_oracle"] for row in oracle_rows],
    }
    known = [i for i, row in enumerate(graders) if row["gold_intent"] is not None]
    composed = [i for i in known if graders[i]["gold_intent"] != "at"]
    arms, row_scores = {}, []
    exacts = {
        name: [
            exact_result(value["actual"], grader["target"])
            for value, grader in zip(values, graders, strict=True)
        ]
        for name, values in arm_values.items()
    }
    for name, values in arm_values.items():
        arms[name] = {
            "known_queries": len(known),
            "known_exact": sum(exacts[name][i] for i in known),
            "known_exact_fraction": sum(exacts[name][i] for i in known) / len(known),
            "composed_queries": len(composed),
            "composed_exact": sum(exacts[name][i] for i in composed),
            "composed_exact_fraction": sum(exacts[name][i] for i in composed)
            / len(composed),
            "hop_calls": sum(value["execution"]["calls"] for value in values),
            "numeric_read_calls": sum(value["numeric_read_calls"] for value in values),
            "numeric_coordinates_read": sum(
                value["numeric_coordinates_read"] for value in values
            ),
        }
    for i, grader in enumerate(graders):
        row_scores.append(
            {
                "index": i,
                "template_id": grader["template_id"],
                "gold_intent": grader["gold_intent"],
                "accepted_intent": decisions[i]["accepted_intent"],
                "exact_by_arm": {name: flags[i] for name, flags in exacts.items()},
            }
        )
    connected = arms["parameter_connected"]["composed_exact"]
    gain_removed = (connected - arms["parameter_removed"]["composed_exact"]) / len(
        composed
    )
    gain_permuted = (connected - arms["parameter_permuted"]["composed_exact"]) / len(
        composed
    )
    checks = {
        "semantic": metrics["known_correct_accepted_fraction"]
        >= GATES["known_correct_accepted_min"]
        and metrics["ood_false_accept_fraction"] <= GATES["ood_false_accept_max"],
        "parameter_oracle_exact": arms["parameter_oracle"]["known_exact_fraction"]
        == GATES["parameter_oracle_exact"],
        "composed_actual_ablation_gain": min(gain_removed, gain_permuted)
        >= GATES["composed_ablation_gain_min"],
    }
    return {
        "routing": metrics,
        "arms": arms,
        "checks": checks,
        "all_preregistered_gates_pass": all(checks.values()),
        "composed_gain_vs_removed": gain_removed,
        "composed_gain_vs_permuted": gain_permuted,
        "oracle_exact_gap": arms["parameter_oracle"]["known_exact_fraction"]
        - arms["parameter_connected"]["known_exact_fraction"],
        "actual_parameter_minus_strong_planner": arms["parameter_connected"][
            "known_exact_fraction"
        ]
        - arms["strong_planner"]["known_exact_fraction"],
        "fresh_route_decisions_exactly_equal": True,
        "rows": row_scores,
    }

